        public TenderBomDialog(TenderProject project)
        {
            _project = project;
            Title = $"Qu\u1ea3n l\u00fd kh\u1ed1i l\u01b0\u1ee3ng \u0111\u1ea5u th\u1ea7u - {project.ProjectName}";
            Width = 1100;
            Height = 700;
            WindowStartupLocation = WindowStartupLocation.CenterScreen;
            Background = BgWindow;

            _wallRows = new ObservableCollection<TenderWallRow>();
            _openingRows = new ObservableCollection<TenderOpeningRow>();
            _cadPreviewTimer = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(300) };
            _cadPreviewTimer.Tick += OnCadPreviewTimerTick;
            _cadSegmentSyncTimer = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(800) };
            _cadSegmentSyncTimer.Tick += OnCadSegmentSyncTimerTick;
            LoadProjectData();

            Content = BuildLayout();
            UiText.NormalizeWindow(this);
            Loaded += (_, _) => UiText.NormalizeWindow(this);
            Loaded += (_, _) => _cadSegmentSyncTimer.Start();
            Deactivated += (_, _) =>
            {
                _cadPreviewTimer.Stop();
                _cadSegmentSyncTimer.Stop();
                _pendingPreviewRow = null;
                _lastCadPreviewKey = null;
                ForceClearHighlight();
            };
            Activated += (_, _) =>
            {
                _cadSegmentSyncTimer.Start();
                if (!_suspendCadOperations
                    && !_isEditingCell
                    && _wallGrid?.SelectedItem is TenderWallRow selectedRow)
                {
                    RequestCadPreview(selectedRow, force: true);
                }
            };
            Closed += (_, _) =>
            {
                _cadPreviewTimer.Stop();
                _cadSegmentSyncTimer.Stop();
            };
        }
        private UIElement BuildLayout()
        {
            var root = new Grid { Margin = new Thickness(12) };
            root.PreviewMouseLeftButtonDown += OnDialogBackgroundMouseDown;
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });                   // 0: header
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) }); // 1: tabs
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });                   // 2: footer

            var header = new TextBlock
            {
                Text = "QU\u1ea2N L\u00dd KH\u1ed0I L\u01af\u1ee2NG CH\u00c0O GI\u00c1",
                FontSize = 18,
                FontWeight = FontWeights.Bold,
                Foreground = FgDark,
                Margin = new Thickness(0, 0, 0, 8)
            };
            Grid.SetRow(header, 0);
            root.Children.Add(header);

            var tabs = new TabControl { FontSize = 13 };
            tabs.Items.Add(CreateInputTab());
            tabs.Items.Add(CreateBomTab());
            tabs.SelectionChanged += (s, e) =>
            {
                if (e.OriginalSource != tabs)
                {
                    return;
                }

                if (tabs.SelectedIndex == 1)
                {
                    try
                    {
                        _cadPreviewTimer.Stop();
                        ClearHighlight();
                        RefreshBomSummary();
                    }
                    catch (Exception ex)
                    {
                        SetStatus($"Kh\u00f4ng th\u1ec3 t\u1ed5ng h\u1ee3p kh\u1ed1i l\u01b0\u1ee3ng: {ex.Message}");
                    }
                }
                else if (tabs.SelectedIndex == 0 && _wallGrid?.SelectedItem is TenderWallRow selectedRow)
                {
                    RequestCadPreview(selectedRow);
                }
            };
            Grid.SetRow(tabs, 1);
            root.Children.Add(tabs);

            var footer = new DockPanel { Margin = new Thickness(0, 10, 0, 0) };

            _lblFooter = new TextBlock
            {
                Text = GetFooterText(),
                FontSize = 13,
                FontWeight = FontWeights.SemiBold,
                Foreground = FgDark,
                VerticalAlignment = VerticalAlignment.Center
            };
            DockPanel.SetDock(_lblFooter, Dock.Left);
            footer.Children.Add(_lblFooter);

            var footerRight = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                HorizontalAlignment = HorizontalAlignment.Right
            };
            var btnClose = new Button
            {
                Content = "\u0110\u00f3ng",
                Width = 90,
                Height = 34,
                Background = AccentBlue,
                Foreground = Brushes.White,
                FontWeight = FontWeights.SemiBold
            };
            btnClose.Click += (s, e) => Close();
            footerRight.Children.Add(btnClose);
            DockPanel.SetDock(footerRight, Dock.Right);
            footer.Children.Add(footerRight);

            Grid.SetRow(footer, 2);
            root.Children.Add(footer);

            return root;
