        private void AddOpeningPreviewLegend(
            IReadOnlyList<double[]> vertices,
            IReadOnlyList<string> legendLines,
            double textHeight,
            Autodesk.AutoCAD.DatabaseServices.ObjectId layerId,
            Autodesk.AutoCAD.DatabaseServices.BlockTableRecord btr,
            Autodesk.AutoCAD.DatabaseServices.Transaction tr)
        {
            if (vertices == null || vertices.Count == 0 || legendLines == null || legendLines.Count == 0)
                return;

            double minX = vertices.Min(v => v[0]);
            double maxY = vertices.Max(v => v[1]);
            double lineStep = Math.Max(100.0, textHeight * 1.1);
            double startX = minX + Math.Max(90.0, textHeight * 0.7);
            double startY = maxY - Math.Max(120.0, textHeight * 0.8);

            for (int i = 0; i < legendLines.Count; i++)
            {
                var p = new Autodesk.AutoCAD.Geometry.Point3d(startX, startY - i * lineStep, 0);
                AddPreviewText(
                    p,
                    legendLines[i],
                    OpeningPreviewTextColorIndex,
                    textHeight,
                    layerId,
                    btr,
                    tr);
            }
        }

        private static double ComputeAdaptivePreviewTextHeight(double spanMm)
        {
            if (spanMm <= 1.0)
                return 120.0;

            return Math.Max(120.0, Math.Min(420.0, spanMm / 140.0));
        }

        private static bool TryResolveOpeningStation(
            TenderOpening opening,
            int fallbackIndex,
            int fallbackCount,
            double drawingLength,
            out double stationStartMm,
            out double stationEndMm)
        {
            stationStartMm = opening.StationStartMm >= 0 ? opening.StationStartMm : opening.CenterStationMm;
            if (stationStartMm < 0)
            {
                if (fallbackCount <= 0)
                {
                    stationEndMm = 0;
                    return false;
                }

                double ratio = (fallbackIndex + 1.0) / (fallbackCount + 1.0);
                stationStartMm = Math.Max(0, ratio * drawingLength - opening.Width * 0.5);
            }

            stationStartMm = Math.Max(0, Math.Min(drawingLength, stationStartMm));
            if (opening.StationEndMm >= stationStartMm)
                stationEndMm = Math.Max(stationStartMm, Math.Min(drawingLength, opening.StationEndMm));
            else
                stationEndMm = Math.Max(stationStartMm, Math.Min(drawingLength, stationStartMm + opening.Width));
            return stationEndMm - stationStartMm > 0.5;
        }

        private static bool TryResolveOpeningPreviewChains(
            IReadOnlyList<double[]> vertices,
            double referenceLengthMm,
            out List<double[]> referenceChain,
            out List<double[]> oppositeChain,
            out double chainLengthMm)
        {
            referenceChain = new List<double[]>();
            oppositeChain = new List<double[]>();
            chainLengthMm = 0;

            if (vertices == null || vertices.Count < 3)
                return false;

            var input = vertices.Select(v => v.ToArray()).ToList();
            double refLength = Math.Max(1.0, referenceLengthMm);
            (List<double[]> A, List<double[]> B, double Score)? best = null;

            bool TryEvaluate(bool horizontal)
            {
                if (!TryBuildDevelopedChains(input, horizontal, out var chainA, out var chainB))
                    return false;

                double lenA = GetPolylineLength(chainA);
                double lenB = GetPolylineLength(chainB);
                if (lenA <= 1.0 || lenB <= 1.0)
                    return false;

                double score = Math.Abs(Math.Min(lenA, lenB) - refLength) + Math.Abs(lenA - lenB) * 0.25;
                if (!best.HasValue || score < best.Value.Score)
                    best = (chainA, chainB, score);
                return true;
            }

            TryEvaluate(horizontal: false);
            TryEvaluate(horizontal: true);

            if (!best.HasValue)
                return false;

            var chosenA = best.Value.A;
            var chosenB = best.Value.B;
            double chosenALength = GetPolylineLength(chosenA);
            double chosenBLength = GetPolylineLength(chosenB);
            bool useA = Math.Abs(chosenALength - refLength) <= Math.Abs(chosenBLength - refLength);

            referenceChain = useA ? chosenA : chosenB;
            oppositeChain = useA ? chosenB : chosenA;
            NormalizeOpeningPreviewChains(referenceChain, oppositeChain, out referenceChain, out oppositeChain);
            chainLengthMm = GetPolylineLength(referenceChain);
            return chainLengthMm > 1.0;
        }

        private static bool TryResolvePolygonDevelopedGeometry(
            IReadOnlyList<double[]> vertices,
            out List<double[]> referenceChain,
            out List<double[]> oppositeChain,
            out double chainLengthMm)
        {
            referenceChain = new List<double[]>();
            oppositeChain = new List<double[]>();
            chainLengthMm = 0;

            if (vertices == null || vertices.Count < 3)
                return false;

            var polygon = vertices
                .Where(v => v != null && v.Length >= 2)
                .Select(v => v.ToArray())
                .ToList();
            if (polygon.Count < 3)
                return false;

            double minX = polygon.Min(v => v[0]);
            double maxX = polygon.Max(v => v[0]);
            double minY = polygon.Min(v => v[1]);
            double maxY = polygon.Max(v => v[1]);
            double spanX = Math.Max(1.0, maxX - minX);
            double spanY = Math.Max(1.0, maxY - minY);

            bool stationAlongY = spanY > spanX;
            if (TryBuildDevelopedChains(polygon, horizontal: stationAlongY, out var primaryChainA, out var primaryChainB))
            {
                NormalizeOpeningPreviewChains(primaryChainA, primaryChainB, out referenceChain, out oppositeChain);
                chainLengthMm = GetPolylineLength(referenceChain);
                if (chainLengthMm > 1.0)
                    return true;
            }

            double estimatedLength = Math.Max(1.0, Math.Max(spanX, spanY));
            return TryResolveOpeningPreviewChains(
                polygon,
                estimatedLength,
                out referenceChain,
                out oppositeChain,
                out chainLengthMm);
        }

        private static void NormalizeOpeningPreviewChains(
            List<double[]> chainA,
            List<double[]> chainB,
            out List<double[]> referenceChain,
            out List<double[]> oppositeChain)
        {
            referenceChain = chainA ?? new List<double[]>();
            oppositeChain = chainB ?? new List<double[]>();
            if (referenceChain.Count < 2 || oppositeChain.Count < 2)
                return;

            var allPoints = referenceChain.Concat(oppositeChain).ToList();
            double minX = allPoints.Min(v => v[0]);
            double maxX = allPoints.Max(v => v[0]);
            double minY = allPoints.Min(v => v[1]);
            double maxY = allPoints.Max(v => v[1]);
            bool stationAlongX = (maxX - minX) >= (maxY - minY);

            double avgA = stationAlongX
                ? referenceChain.Average(v => v[1])
                : referenceChain.Average(v => v[0]);
            double avgB = stationAlongX
                ? oppositeChain.Average(v => v[1])
                : oppositeChain.Average(v => v[0]);

            if (avgB < avgA)
            {
                var temp = referenceChain;
                referenceChain = oppositeChain;
                oppositeChain = temp;
            }

            double direct = DistanceSquared(referenceChain[0], oppositeChain[0])
                          + DistanceSquared(referenceChain[^1], oppositeChain[^1]);
            double reversed = DistanceSquared(referenceChain[0], oppositeChain[^1])
                            + DistanceSquared(referenceChain[^1], oppositeChain[0]);
            if (reversed < direct)
            {
                oppositeChain = oppositeChain
                    .AsEnumerable()
                    .Reverse()
                    .Select(v => v.ToArray())
                    .ToList();
            }

            bool reverseReferenceDirection = stationAlongX
                ? referenceChain[^1][0] < referenceChain[0][0]
                : referenceChain[^1][1] < referenceChain[0][1];
            if (reverseReferenceDirection)
            {
                referenceChain = referenceChain
                    .AsEnumerable()
                    .Reverse()
                    .Select(v => v.ToArray())
                    .ToList();
                oppositeChain = oppositeChain
                    .AsEnumerable()
                    .Reverse()
                    .Select(v => v.ToArray())
                    .ToList();
            }
        }

        private static double DistanceSquared(double[] a, double[] b)
        {
            if (a == null || b == null || a.Length < 2 || b.Length < 2)
                return double.MaxValue;

            double dx = a[0] - b[0];
            double dy = a[1] - b[1];
            return dx * dx + dy * dy;
        }

        private static bool TryGetDirectionAndLength(
            double[] from,
            double[] to,
            out double[] direction,
            out double length)
        {
            direction = Array.Empty<double>();
            length = 0;
            if (from == null || to == null || from.Length < 2 || to.Length < 2)
                return false;

            double dx = to[0] - from[0];
            double dy = to[1] - from[1];
            length = Math.Sqrt(dx * dx + dy * dy);
            if (length <= 1e-6)
                return false;

            direction = new[] { dx / length, dy / length };
            return true;
        }

        private static List<TenderHeightSegment> BuildPreviewHeightSegments(TenderWallRow row, double drawingLength)
        {
            var segments = (row.HeightSegments ?? new List<TenderHeightSegment>())
                .Where(s => s != null && s.LengthMm > 0 && s.HeightMm > 0)
                .Select(s => new TenderHeightSegment
                {
                    LengthMm = s.LengthMm,
                    HeightMm = s.HeightMm,
                    CadHandle = s.CadHandle
                })
                .ToList();

            if (segments.Count == 0)
            {
                return new List<TenderHeightSegment>
                {
                    new TenderHeightSegment
                    {
                        LengthMm = Math.Max(1.0, drawingLength),
                        HeightMm = Math.Max(1.0, row.Height)
                    }
                };
            }

            double totalLength = segments.Sum(s => Math.Max(0, s.LengthMm));
            if (totalLength > 1.0 && Math.Abs(totalLength - drawingLength) > 1.0)
            {
                double scale = drawingLength / totalLength;
                foreach (var segment in segments)
                    segment.LengthMm = Math.Max(1.0, segment.LengthMm * scale);
            }

            return segments;
        }

        private static bool HasNonOrthogonalEdges(IReadOnlyList<double[]> vertices)
        {
            if (vertices == null || vertices.Count < 2)
                return false;

            const double tolerance = 1.0;
            int count = vertices.Count;
            for (int i = 0; i < count; i++)
            {
                var p1 = vertices[i];
                var p2 = vertices[(i + 1) % count];
                if (p1.Length < 2 || p2.Length < 2)
                    continue;

                double dx = Math.Abs(p2[0] - p1[0]);
                double dy = Math.Abs(p2[1] - p1[1]);

                // Cáº¡nh khÃ´ng ngang cÅ©ng khÃ´ng dá»c => Ä‘a giÃ¡c xiÃªn.
                if (dx > tolerance && dy > tolerance)
                    return true;
            }

            return false;
        }

        private bool TryAddDevelopedPanelPreviewLines(
            List<double[]> vertices,
            TenderWallRow row,
            Autodesk.AutoCAD.DatabaseServices.ObjectId layerId,
            Autodesk.AutoCAD.DatabaseServices.BlockTableRecord btr,
            Autodesk.AutoCAD.DatabaseServices.Transaction tr,
            bool enableDetailedLog,
            ref int previewLineCount)
        {
            bool isAreaPolygon = row.PolygonVertices != null && row.PolygonVertices.Count >= 3;
            bool isRotatedRectanglePreview = row.PolygonVertices == null && vertices.Count == 4;
            if (!isAreaPolygon && !isRotatedRectanglePreview)
                return false;

            bool horizontal = string.Equals(row.LayoutDirection, "Ngang", StringComparison.OrdinalIgnoreCase);
            if (!TryBuildDevelopedChains(vertices, horizontal, out var chainA, out var chainB))
            {
                if (enableDetailedLog)
                    PluginLogger.Warn($"TenderPreview.PanelLines.DevelopedFailed | row={row.Name} | reason=build-chains");
                return false;
            }

            if (enableDetailedLog)
            {
                PluginLogger.Info(
                    $"TenderPreview.PanelLines.DevelopedStart | row={row.Name} | horizontal={horizontal} | " +
                    $"chainA={FormatPreviewVertices(chainA)} | chainB={FormatPreviewVertices(chainB)}");
            }

            if (!horizontal)
            {
                double referenceLengthA = GetPolylineLength(chainA);
                double referenceLengthB = GetPolylineLength(chainB);
                var referenceChain = referenceLengthA <= referenceLengthB ? chainA : chainB;
                var oppositeChain = ReferenceEquals(referenceChain, chainA) ? chainB : chainA;
                double developedLength = GetPolylineLength(referenceChain);
                if (developedLength <= row.PanelWidth + 1.0)
                    return true;

                bool addedAny = false;
                for (double distance = row.PanelWidth; distance < developedLength - 1.0; distance += row.PanelWidth)
                {
                    if (!TryGetPointAndDirectionAlongPolyline(referenceChain, distance, out var start, out var direction))
                    {
                        if (enableDetailedLog)
                            PluginLogger.Warn($"TenderPreview.PanelLines.DevelopedSkip | row={row.Name} | distance={distance:F0} | reason=point-direction");
                        continue;
                    }

                    if (!TryIntersectNormalWithPolyline(start, direction, oppositeChain, out var end))
                    {
                        if (enableDetailedLog)
                            PluginLogger.Warn($"TenderPreview.PanelLines.DevelopedSkip | row={row.Name} | distance={distance:F0} | reason=normal-intersection");
                        continue;
                    }

                    AddPreviewLine(
                        new Autodesk.AutoCAD.Geometry.Point3d(start[0], start[1], 0),
                        new Autodesk.AutoCAD.Geometry.Point3d(end[0], end[1], 0),
                        PanelPreviewColorIndex,
                        Autodesk.AutoCAD.DatabaseServices.LineWeight.LineWeight025,
                        layerId,
                        btr,
                        tr);
                    previewLineCount++;
                    if (enableDetailedLog)
                    {
                        PluginLogger.Info(
                            $"TenderPreview.PanelLines.DevelopedLine | row={row.Name} | distance={distance:F0} | " +
                            $"start=({start[0]:F0},{start[1]:F0}) | end=({end[0]:F0},{end[1]:F0})");
                    }
                    addedAny = true;
                }

                return addedAny;
            }

            double lengthA = GetPolylineLength(chainA);
            double lengthB = GetPolylineLength(chainB);
            double developmentLength = Math.Max(lengthA, lengthB);
            if (developmentLength <= row.PanelWidth + 1.0)
                return true;

            for (double distance = row.PanelWidth; distance < developmentLength - 1.0; distance += row.PanelWidth)
            {
                double ratio = distance / developmentLength;
                var start = GetPointAlongPolyline(chainA, ratio);
                var end = GetPointAlongPolyline(chainB, ratio);
                if (start == null || end == null)
                {
                    if (enableDetailedLog)
                        PluginLogger.Warn($"TenderPreview.PanelLines.DevelopedSkip | row={row.Name} | distance={distance:F0} | reason=point-along");
                    continue;
                }

                AddPreviewLine(
                    new Autodesk.AutoCAD.Geometry.Point3d(start[0], start[1], 0),
                    new Autodesk.AutoCAD.Geometry.Point3d(end[0], end[1], 0),
                    PanelPreviewColorIndex,
                    Autodesk.AutoCAD.DatabaseServices.LineWeight.LineWeight025,
                    layerId,
                    btr,
                    tr);
                previewLineCount++;
                if (enableDetailedLog)
                {
                    PluginLogger.Info(
                        $"TenderPreview.PanelLines.DevelopedLine | row={row.Name} | distance={distance:F0} | " +
                        $"start=({start[0]:F0},{start[1]:F0}) | end=({end[0]:F0},{end[1]:F0})");
                }
            }

            return true;
        }

        private static string FormatPreviewVertices(IReadOnlyList<double[]> vertices)
        {
            if (vertices == null || vertices.Count == 0)
                return "[]";

            return "[" + string.Join(";", vertices.Select(v =>
            {
                if (v == null || v.Length < 2)
                    return "(?)";
                return $"({v[0]:F0},{v[1]:F0})";
            })) + "]";
        }

        private static string FormatScanSegments(IReadOnlyList<(double Start, double End)> segments)
        {
            if (segments == null || segments.Count == 0)
                return "[]";

            return "[" + string.Join(";", segments.Select(s => $"({s.Start:F0}->{s.End:F0})")) + "]";
        }

        private static string FormatPanelBreakdownSummary(TenderWallRow row)
        {
            try
            {
                var model = row.ToModel();
                var breakdown = model.GetPanelBreakdown();
                if (breakdown.Count == 0)
                    return "[]";

                return "[" + string.Join(";", breakdown.Select(e =>
                    $"{e.Label}:{e.WidthMm:F0}x{e.LengthMm:F0}x{e.Count}")) + "]";
            }
            catch (Exception ex)
            {
                return $"[error:{ex.Message}]";
            }
        }

        private static bool TryBuildDevelopedChains(
            List<double[]> vertices,
            bool horizontal,
            out List<double[]> chainA,
            out List<double[]> chainB)
        {
            chainA = new List<double[]>();
            chainB = new List<double[]>();

            if (vertices.Count < 3)
                return false;

            int startIndex = 0;
            int endIndex = 0;
            double minAxis = double.MaxValue;
            double maxAxis = double.MinValue;

            for (int i = 0; i < vertices.Count; i++)
            {
                double axis = horizontal ? vertices[i][1] : vertices[i][0];
                if (axis < minAxis)
                {
                    minAxis = axis;
                    startIndex = i;
                }

                if (axis > maxAxis)
                {
                    maxAxis = axis;
                    endIndex = i;
                }
            }

            if (startIndex == endIndex)
                return false;

            var forward = BuildVertexChain(vertices, startIndex, endIndex, 1);
            var backward = BuildVertexChain(vertices, startIndex, endIndex, -1);
            if (forward.Count < 2 || backward.Count < 2)
                return false;

            double forwardMeasure = forward.Average(v => horizontal ? v[0] : v[1]);
            double backwardMeasure = backward.Average(v => horizontal ? v[0] : v[1]);

            if (forwardMeasure <= backwardMeasure)
            {
                chainA = forward;
                chainB = backward;
            }
            else
            {
                chainA = backward;
                chainB = forward;
            }

            return true;
        }

        private static List<double[]> BuildVertexChain(
            List<double[]> vertices,
            int startIndex,
            int endIndex,
            int step)
        {
            var chain = new List<double[]>();
            int count = vertices.Count;
            int index = startIndex;

            while (true)
            {
                chain.Add(vertices[index].ToArray());
                if (index == endIndex)
                    break;

                index = (index + step + count) % count;
                if (chain.Count > count + 1)
                    break;
            }

            return chain;
        }



        private static bool TryGetPointAndDirectionAlongPolyline(
            List<double[]> vertices,
            double distance,
            out double[] point,
            out double[] direction)
        {
            point = Array.Empty<double>();
            direction = Array.Empty<double>();

            if (vertices.Count < 2)
                return false;

            double walked = 0;
            for (int i = 0; i + 1 < vertices.Count; i++)
            {
                double[] start = vertices[i];
                double[] end = vertices[i + 1];
                double dx = end[0] - start[0];
                double dy = end[1] - start[1];
                double segmentLength = Math.Sqrt(dx * dx + dy * dy);
                if (segmentLength <= 1e-6)
                    continue;

                if (walked + segmentLength >= distance)
                {
                    double t = (distance - walked) / segmentLength;
                    point = new[]
                    {
                        start[0] + dx * t,
                        start[1] + dy * t
                    };
                    direction = new[]
                    {
                        dx / segmentLength,
                        dy / segmentLength
                    };
                    return true;
                }

                walked += segmentLength;
            }

            if (vertices.Count >= 2)
            {
                double[] start = vertices[^2];
                double[] end = vertices[^1];
                double dx = end[0] - start[0];
                double dy = end[1] - start[1];
                double segmentLength = Math.Sqrt(dx * dx + dy * dy);
                if (segmentLength > 1e-6)
                {
                    point = end.ToArray();
                    direction = new[]
                    {
                        dx / segmentLength,
                        dy / segmentLength
                    };
                    return true;
                }
            }

            return false;
        }

        private static bool TryIntersectNormalWithPolyline(
            double[] origin,
            double[] direction,
            List<double[]> polyline,
            out double[] intersection)
        {
            intersection = Array.Empty<double>();
            if (origin.Length < 2 || direction.Length < 2 || polyline.Count < 2)
                return false;

            double nx = -direction[1];
            double ny = direction[0];
            double[] centroid = GetPolylineCentroid(polyline);
            double towardCentroid = (centroid[0] - origin[0]) * nx + (centroid[1] - origin[1]) * ny;
            if (towardCentroid < 0)
            {
                nx = -nx;
                ny = -ny;
            }

            double bestT = double.MaxValue;
            bool found = false;
            for (int i = 0; i + 1 < polyline.Count; i++)
            {
                if (!TryIntersectRayWithSegment(
                        origin[0],
                        origin[1],
                        nx,
                        ny,
                        polyline[i][0],
                        polyline[i][1],
                        polyline[i + 1][0],
                        polyline[i + 1][1],
                        out double rayT,
                        out _))
                {
                    continue;
                }

                if (rayT <= 1.0 || rayT >= bestT)
                    continue;

                bestT = rayT;
                found = true;
            }

            if (!found)
                return false;

            intersection = new[]
            {
                origin[0] + nx * bestT,
                origin[1] + ny * bestT
            };
            return true;
        }


        private static bool TryIntersectRayWithSegment(
            double px,
            double py,
            double rx,
            double ry,
            double ax,
            double ay,
            double bx,
            double by,
            out double rayT,
            out double segmentU)
        {
            rayT = 0;
            segmentU = 0;

            double sx = bx - ax;
            double sy = by - ay;
            double denominator = Cross(rx, ry, sx, sy);
            if (Math.Abs(denominator) <= 1e-6)
                return false;

            double qpx = ax - px;
            double qpy = ay - py;
            rayT = Cross(qpx, qpy, sx, sy) / denominator;
            segmentU = Cross(qpx, qpy, rx, ry) / denominator;
            return rayT >= 0 && segmentU >= -1e-6 && segmentU <= 1 + 1e-6;
        }


        private void AddSuspensionPreviewLines(
            List<double[]> vertices,
            bool runAlongX,
            IReadOnlyList<double> positions,
            double spacingMm,
            string linePrefix,
            short colorIndex,
            Autodesk.AutoCAD.DatabaseServices.LineWeight lineWeight,
            bool useCircleMarker,
            bool drawMarkers,
            bool drawLabels,
            Autodesk.AutoCAD.DatabaseServices.ObjectId layerId,
            Autodesk.AutoCAD.DatabaseServices.BlockTableRecord btr,
            Autodesk.AutoCAD.DatabaseServices.Transaction tr)
        {
            for (int index = 0; index < positions.Count; index++)
            {
                double pos = positions[index];
                var segments = GetScanSegments(vertices, pos, runAlongX);
                foreach (var segment in segments)
                {
                    var start = runAlongX
                        ? new Autodesk.AutoCAD.Geometry.Point3d(segment.Start, pos, 0)
                        : new Autodesk.AutoCAD.Geometry.Point3d(pos, segment.Start, 0);
                    var end = runAlongX
                        ? new Autodesk.AutoCAD.Geometry.Point3d(segment.End, pos, 0)
                        : new Autodesk.AutoCAD.Geometry.Point3d(pos, segment.End, 0);

                    AddPreviewLine(start, end, colorIndex, lineWeight, layerId, btr, tr);
                    if (drawMarkers)
                    {
                        AddSuspensionPointMarkers(
                            start,
                            end,
                            colorIndex,
                            useCircleMarker,
                            layerId,
                            btr,
                            tr);
                    }

                    if (drawLabels)
                    {
                        AddSuspensionLineLabel(
                            start,
                            end,
                            $"{linePrefix}{index + 1} @{spacingMm:F0}",
                            colorIndex,
                            layerId,
                            btr,
                            tr);
                    }
                }
            }
        }

        private void AddSuspensionPreviewLines(
            List<double[]> vertices,
            bool runAlongX,
            bool divideFromMaxSide,
            double cycleSpacingMm,
            double initialOffsetMm,
            int lineCount,
            string linePrefix,
            short colorIndex,
            Autodesk.AutoCAD.DatabaseServices.LineWeight lineWeight,
            bool useCircleMarker,
            bool drawMarkers,
            bool drawLabels,
            Autodesk.AutoCAD.DatabaseServices.ObjectId layerId,
            Autodesk.AutoCAD.DatabaseServices.BlockTableRecord btr,
            Autodesk.AutoCAD.DatabaseServices.Transaction tr)
        {
            var positions = BuildSuspensionLinePositions(vertices, runAlongX, divideFromMaxSide, cycleSpacingMm, initialOffsetMm, lineCount);
            AddSuspensionPreviewLines(
                vertices,
                runAlongX,
                positions,
                initialOffsetMm,
                linePrefix,
                colorIndex,
                lineWeight,
                useCircleMarker,
                drawMarkers,
                drawLabels,
                layerId,
                btr,
                tr);
        }

        private static List<double> BuildSuspensionLinePositions(
            List<double[]> vertices,
            bool runAlongX,
            bool divideFromMaxSide,
            double cycleSpacingMm,
            double initialOffsetMm,
            int lineCount)
        {
            var positions = new List<double>();
            if (lineCount <= 0 || cycleSpacingMm <= 0 || initialOffsetMm <= 0)
                return positions;

            double min = runAlongX ? vertices.Min(v => v[1]) : vertices.Min(v => v[0]);
            double max = runAlongX ? vertices.Max(v => v[1]) : vertices.Max(v => v[0]);
            if (max - min <= initialOffsetMm)
                return positions;

            const double edgeOffset = 0.5;
            double start = divideFromMaxSide
                ? max - initialOffsetMm
                : min + initialOffsetMm;
            double step = divideFromMaxSide ? -cycleSpacingMm : cycleSpacingMm;

            for (double pos = start;
                 positions.Count < lineCount && pos > min + edgeOffset - 1e-6 && pos < max - edgeOffset + 1e-6;
                 pos += step)
            {
                if (positions.Count == 0 || Math.Abs(positions[positions.Count - 1] - pos) > 1.0)
                    positions.Add(pos);
            }

            return positions;
        }

        private static List<(double Start, double End)> GetScanSegments(
            List<double[]> vertices,
            double scanPos,
            bool horizontalLine)
        {
            var intersections = new List<double>();
            int count = vertices.Count;

            for (int i = 0; i < count; i++)
            {
                var p1 = vertices[i];
                var p2 = vertices[(i + 1) % count];

                double s1 = horizontalLine ? p1[1] : p1[0];
                double s2 = horizontalLine ? p2[1] : p2[0];
                double m1 = horizontalLine ? p1[0] : p1[1];
                double m2 = horizontalLine ? p2[0] : p2[1];

                if ((s1 <= scanPos && s2 > scanPos) || (s2 <= scanPos && s1 > scanPos))
                {
                    double t = (scanPos - s1) / (s2 - s1);
                    intersections.Add(m1 + t * (m2 - m1));
                }
            }

            intersections.Sort();
            var segments = new List<(double Start, double End)>();
            for (int i = 0; i + 1 < intersections.Count; i += 2)
            {
                double start = intersections[i];
                double end = intersections[i + 1];
                if (end - start > 1.0)
                    segments.Add((start, end));
            }

            return segments;
        }

        private void AddPreviewLine(
            Autodesk.AutoCAD.Geometry.Point3d start,
            Autodesk.AutoCAD.Geometry.Point3d end,
            short colorIndex,
            Autodesk.AutoCAD.DatabaseServices.LineWeight lineWeight,
            Autodesk.AutoCAD.DatabaseServices.ObjectId layerId,
            Autodesk.AutoCAD.DatabaseServices.BlockTableRecord btr,
            Autodesk.AutoCAD.DatabaseServices.Transaction tr)
        {
            var line = new Autodesk.AutoCAD.DatabaseServices.Line(start, end)
            {
                LayerId = layerId,
                ColorIndex = colorIndex,
                LineWeight = lineWeight
            };

            btr.AppendEntity(line);
            tr.AddNewlyCreatedDBObject(line, true);
            _previewEntityIds.Add(line.ObjectId);
        }

        private void AddSuspensionPointMarkers(
            Autodesk.AutoCAD.Geometry.Point3d start,
            Autodesk.AutoCAD.Geometry.Point3d end,
            short colorIndex,
            bool useCircleMarker,
            Autodesk.AutoCAD.DatabaseServices.ObjectId layerId,
            Autodesk.AutoCAD.DatabaseServices.BlockTableRecord btr,
            Autodesk.AutoCAD.DatabaseServices.Transaction tr)
        {
            double length = start.DistanceTo(end);
            if (length <= 1.0)
                return;

            int pointCount = Math.Max(1, (int)Math.Ceiling(length / TenderBomCalculator.ColdStorageSuspensionPointSpacingMm));
            double actualSpacing = length / pointCount;
            var direction = (end - start).GetNormal();
            var normal = new Autodesk.AutoCAD.Geometry.Vector3d(-direction.Y, direction.X, 0.0);
            const double markerSize = 60.0;

            for (int i = 0; i < pointCount; i++)
            {
                double distance = actualSpacing * (i + 0.5);
                var center = start + (direction * distance);

                if (useCircleMarker)
                {
                    AddPreviewCircle(center, markerSize, colorIndex, layerId, btr, tr);
                }
                else
                {
                    AddPreviewCross(center, direction, normal, markerSize, colorIndex, layerId, btr, tr);
                }
            }
        }

        private void AddPreviewCircle(
            Autodesk.AutoCAD.Geometry.Point3d center,
            double radius,
            short colorIndex,
            Autodesk.AutoCAD.DatabaseServices.ObjectId layerId,
            Autodesk.AutoCAD.DatabaseServices.BlockTableRecord btr,
            Autodesk.AutoCAD.DatabaseServices.Transaction tr)
        {
            var circle = new Autodesk.AutoCAD.DatabaseServices.Circle(center, Autodesk.AutoCAD.Geometry.Vector3d.ZAxis, radius)
            {
                LayerId = layerId,
                ColorIndex = colorIndex,
                LineWeight = Autodesk.AutoCAD.DatabaseServices.LineWeight.LineWeight025
            };

            btr.AppendEntity(circle);
            tr.AddNewlyCreatedDBObject(circle, true);
            _previewEntityIds.Add(circle.ObjectId);
        }

        private void AddPreviewCross(
            Autodesk.AutoCAD.Geometry.Point3d center,
            Autodesk.AutoCAD.Geometry.Vector3d direction,
            Autodesk.AutoCAD.Geometry.Vector3d normal,
            double markerSize,
            short colorIndex,
            Autodesk.AutoCAD.DatabaseServices.ObjectId layerId,
            Autodesk.AutoCAD.DatabaseServices.BlockTableRecord btr,
            Autodesk.AutoCAD.DatabaseServices.Transaction tr)
        {
            AddPreviewLine(
                center - direction * markerSize,
                center + direction * markerSize,
                colorIndex,
                Autodesk.AutoCAD.DatabaseServices.LineWeight.LineWeight025,
                layerId,
                btr,
                tr);

            AddPreviewLine(
                center - normal * markerSize,
                center + normal * markerSize,
                colorIndex,
                Autodesk.AutoCAD.DatabaseServices.LineWeight.LineWeight025,
                layerId,
                btr,
                tr);
        }

        private void AddSuspensionLineLabel(
            Autodesk.AutoCAD.Geometry.Point3d start,
            Autodesk.AutoCAD.Geometry.Point3d end,
            string text,
            short colorIndex,
            Autodesk.AutoCAD.DatabaseServices.ObjectId layerId,
            Autodesk.AutoCAD.DatabaseServices.BlockTableRecord btr,
            Autodesk.AutoCAD.DatabaseServices.Transaction tr)
        {
            var direction = end - start;
            if (direction.Length <= 1.0)
                return;

            var normal = new Autodesk.AutoCAD.Geometry.Vector3d(-direction.Y, direction.X, 0.0).GetNormal();
            var labelPoint = start + direction.MultiplyBy(0.08) + normal.MultiplyBy(140.0);
            AddPreviewText(labelPoint, text, colorIndex, 140.0, layerId, btr, tr);
        }

                private void AddPreviewText(
            Autodesk.AutoCAD.Geometry.Point3d position,
            string text,
            short colorIndex,
            double height,
            Autodesk.AutoCAD.DatabaseServices.ObjectId layerId,
            Autodesk.AutoCAD.DatabaseServices.BlockTableRecord btr,
            Autodesk.AutoCAD.DatabaseServices.Transaction tr)
        {
            var dbText = new Autodesk.AutoCAD.DatabaseServices.DBText
            {
                Position = position,
                Height = height,
                TextString = text,
                LayerId = layerId,
                ColorIndex = colorIndex,
                TextStyleId = BlockManager.EnsureArialStyle(btr.Database, tr)
            };

            btr.AppendEntity(dbText);
            tr.AddNewlyCreatedDBObject(dbText, true);
            _previewEntityIds.Add(dbText.ObjectId);
        }

        private void OnEditAccessories(object sender, RoutedEventArgs e)
        {
            try
            {
                _project.Accessories = AccessoryDataManager.NormalizeConfiguredAccessories(_project.Accessories);
                var dialog = new TenderAccessoryEditorDialog(
                    _project.Accessories,
                    _project.Specs.Select(spec => spec.Key));

                dialog.Owner = this;
                bool? result = dialog.ShowDialog();
                if (result != true)
                    return;

                _project.Accessories = dialog.GetAccessories();
                RefreshBomSummary();
                SetStatus($"\u0110\u00e3 c\u1eadp nh\u1eadt {_project.Accessories.Count} d\u00f2ng ph\u1ee5 ki\u1ec7n");
            }
            catch (Exception ex)
            {
                SetStatus($"L\u1ed7i s\u1eeda ph\u1ee5 ki\u1ec7n: {ex.Message}");
